// ============================================================
// LOG FINAL - Resumen consolidado de la ejecución
// ============================================================

const kpi = $input.first().json;

const summary = {
  ejecutado_en: kpi.run_timestamp,
  pipeline:     kpi.pipeline,
  resumen: {
    ingestados:  kpi.kpis.total_records_ingested,
    validos:     kpi.kpis.records_valid,
    invalidos:   kpi.kpis.records_invalid,
    cargados:    kpi.kpis.records_loaded,
    completitud: kpi.kpis.completitud_pct + '%',
    tasa_error:  kpi.kpis.tasa_error_pct  + '%'
  },
  alertas:   kpi.alerts,
  resultado: kpi.alerts.length === 0 ? '✅ PIPELINE EXITOSO' : '⚠️ PIPELINE CON ALERTAS'
};

console.log('============================================');
console.log('[PIPELINE FINALIZADO]', summary.resultado);
console.log('Completitud:', summary.resumen.completitud);
console.log('Tasa de error:', summary.resumen.tasa_error);
console.log('Registros cargados:', summary.resumen.cargados);
console.log('============================================');

return [{ json: summary }];

// ============================================================
// KPI MONITOREO - Lee logs directamente desde nodos anteriores
// ============================================================

// Leer outputs de nodos anteriores directamente
let ingestLog, cleanLog, validationLog, loadLog;

try {
  const ingestaOutput = $('ETAPA 1c - Log de Ingesta').first().json;
  ingestLog = ingestaOutput.ingestLog || {
    records_read: $('ETAPA 1c - Log de Ingesta').all().length,
    timestamp: new Date().toISOString(),
    source: 'ventas_ecommerce.xlsx',
    status: 'OK'
  };
} catch(e) { ingestLog = { records_read: 0 }; }

try {
  cleanLog = $('ETAPA 2 - Limpieza y Transformación').first().json.log || {};
} catch(e) { cleanLog = {}; }

try {
  validationLog = $('ETAPA 3 - Validación Estructural y Semántica').first().json.log || {};
} catch(e) { validationLog = {}; }

const totalRecords   = ingestLog.records_read          || 0;
const validRecords   = validationLog.valid_records     || 0;
const invalidRecords = validationLog.invalid_records   || 0;
const loadedRecords  = validRecords; // los que pasaron validación

const completitud = totalRecords > 0 ? ((validRecords / totalRecords) * 100).toFixed(1) : 0;
const tasaError   = totalRecords > 0 ? ((invalidRecords / totalRecords) * 100).toFixed(1) : 0;

const kpiReport = {
  pipeline:      'Pipeline DataOps E-commerce',
  run_timestamp: new Date().toISOString(),
  kpis: {
    total_records_ingested: totalRecords,
    records_valid:          validRecords,
    records_invalid:        invalidRecords,
    records_loaded:         loadedRecords,
    completitud_pct:        parseFloat(completitud),
    tasa_error_pct:         parseFloat(tasaError)
  },
  alerts: [
    ...(parseFloat(tasaError)   > 5  ? ['⚠️ ALERTA: Tasa de error supera el 5%'] : []),
    ...(parseFloat(completitud) < 95 ? ['⚠️ ALERTA: Completitud bajo el 95%']    : [])
  ],
  stage_logs: { ingest: ingestLog, clean: cleanLog, validation: validationLog }
};

console.log('[KPI] Completitud:', completitud + '%', '| Error:', tasaError + '%');
console.log('[KPI] Alertas activas:', kpiReport.alerts.length);

return [{ json: kpiReport }];

// ============================================================
// CUARENTENA: Registros Inválidos → Hoja 'cuarentena'
// ============================================================

const input = $input.first().json;
const invalid = input.invalidData || [];

console.log('[CUARENTENA] Registros en cuarentena:', invalid.length);

if (invalid.length === 0) {
  return [{ json: { message: 'Sin registros inválidos en esta ejecución' } }];
}

return invalid.map(r => ({
  json: {
    order_id:    r.order_id || 'NULL',
    raw_data:    JSON.stringify(r),
    issues:      (r._issues || []).join(' | '),
    detected_at: new Date().toISOString()
  }
}));

// ============================================================
// ETAPA 4: PREPARAR CARGA A GOOGLE SHEETS
// ============================================================

const input = $input.first().json;
const valid = input.validData;

const loadLog = {
  stage:           'CARGA',
  timestamp:       new Date().toISOString(),
  records_to_load: valid.length,
  target:          'Google Sheets - Hoja: ventas_limpias',
  status:          'READY'
};

console.log('[CARGA] Registros listos para Google Sheets:', valid.length);

return valid.map((r, i) => ({
  json: {
    order_id:      r.order_id,
    customer_name: r.customer_name,
    product:       r.product,
    quantity:      r.quantity,
    price:         r.price,
    order_date:    r.date,
    email:         r.email,
    region:        r.region,
    loaded_at:     new Date().toISOString(),
    _pipeline_logs: i === 0 ? {
      ingest:     input.ingestLog,
      clean:      input.cleanLog,
      validation: input.log,
      load:       loadLog
    } : null
  }
}));

// ============================================================
// ETAPA 3: VALIDACIÓN ESTRUCTURAL Y SEMÁNTICA
// ============================================================

const input = $input.first().json;
const data  = input.cleanedData;

if (!data || !Array.isArray(data)) {
  throw new Error('cleanedData no encontrado o no es un array. Verifica que el nodo de Limpieza esté conectado correctamente.');
}

const valid   = [];
const invalid = [];

const emailRegex   = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const validRegions = ['RM','BIO','VAL','ARI','TAR','ATK','COQ','OHI','MAU','LRI','LLA','AYS','MAG'];

for (const row of data) {
  const issues = [...(row._errors || [])];

  // Validación ESTRUCTURAL
  if (!row.order_id)      issues.push('[STRUCT] order_id es nulo o vacío');
  if (!row.customer_name) issues.push('[STRUCT] customer_name vacío');
  if (!row.product)       issues.push('[STRUCT] product vacío');
  if (!row.date)          issues.push('[STRUCT] date vacío');

  // Validación SEMÁNTICA
  if (row.quantity <= 0 || isNaN(row.quantity)) issues.push('[SEM] quantity debe ser > 0, valor: ' + row.quantity);
  if (row.price   <= 0 || isNaN(row.price))    issues.push('[SEM] price debe ser > 0, valor: ' + row.price);
  if (row.email && !emailRegex.test(row.email)) issues.push('[SEM] email inválido: ' + row.email);
  if (row.region && !validRegions.includes(row.region)) issues.push('[SEM] región no reconocida: ' + row.region);

  const clean = { ...row };
  delete clean._errors;

  if (issues.length === 0) {
    valid.push({ ...clean, _valid: true });
  } else {
    invalid.push({ ...clean, _valid: false, _issues: issues });
  }
}

const validationLog = {
  stage:           'VALIDACION',
  timestamp:       new Date().toISOString(),
  total_records:   data.length,
  valid_records:   valid.length,
  invalid_records: invalid.length,
  invalid_detail:  invalid.map(r => ({ order_id: r.order_id, issues: r._issues })),
  status:          invalid.length === 0 ? 'OK' : 'WARNING'
};

console.log('[VALIDACION] Válidos:', valid.length, '| Inválidos:', invalid.length);

return [{
  json: {
    validData:   valid,
    invalidData: invalid,
    log:         validationLog,
    ingestLog:   input.ingestLog,
    cleanLog:    input.log
  }
}];

// ============================================================
// ETAPA 2: LIMPIEZA Y TRANSFORMACIÓN
// Recibe los items del Spreadsheet File (1 item = 1 fila)
// y los limpia uno por uno.
// ============================================================

const items = $input.all();
const errors = [];
const cleaned = [];

// Función para convertir número serial de Excel a fecha ISO
function excelSerialToDate(serial) {
  if (typeof serial === 'number') {
    const excelEpoch = new Date(1899, 11, 30);
    const date = new Date(excelEpoch.getTime() + serial * 86400000);
    return date.toISOString().split('T')[0];
  }
  return String(serial);
}

for (const item of items) {
  const row = { ...item.json };
  const rowErrors = [];

  // Limpiar nulls
  for (const key of Object.keys(row)) {
    if (row[key] === null || row[key] === undefined) row[key] = '';
  }

  // Normalizar fecha
  if (row.date) {
    if (typeof row.date === 'number') {
      row.date = excelSerialToDate(row.date);
    } else {
      row.date = String(row.date).replace(/\//g, '-').trim();
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(row.date)) {
      rowErrors.push('Formato de fecha inválido: ' + row.date);
    }
  }

  // Limpiar strings
  if (row.customer_name) row.customer_name = String(row.customer_name).trim();
  if (row.product)       row.product       = String(row.product).trim();
  if (row.region)        row.region        = String(row.region).trim().toUpperCase();
  if (row.email)         row.email         = String(row.email).trim().toLowerCase();
  if (row.order_id)      row.order_id      = String(row.order_id).trim();

  // Convertir numéricos
  row.quantity = parseInt(row.quantity, 10);
  row.price    = parseFloat(row.price);

  if (isNaN(row.quantity)) rowErrors.push('quantity no es número: ' + item.json.quantity);
  if (isNaN(row.price))    rowErrors.push('price no es número: ' + item.json.price);

  row._errors = rowErrors;
  cleaned.push(row);

  if (rowErrors.length > 0) errors.push({ order_id: row.order_id, errors: rowErrors });
}

const cleanLog = {
  stage:               'LIMPIEZA',
  timestamp:           new Date().toISOString(),
  records_processed:   cleaned.length,
  records_with_errors: errors.length,
  error_detail:        errors,
  status:              'OK'
};

console.log('[LIMPIEZA] Procesados:', cleaned.length, '| Con errores:', errors.length);

// Pasar ingestLog desde el primer item si existe, o construir uno básico
const ingestLog = items[0]?.json?.ingestLog || {
  stage:        'INGESTA',
  timestamp:    new Date().toISOString(),
  records_read: cleaned.length,
  source:       'ventas_ecommerce.xlsx',
  status:       'OK'
};

return [{ json: { cleanedData: cleaned, log: cleanLog, ingestLog } }];

// ============================================================
// ETAPA 1c: LOG DE INGESTA
// Recibe los items del Spreadsheet File y genera el log.
// NO agrupa los datos, los pasa tal cual al siguiente nodo.
// ============================================================

const items = $input.all();

const ingestLog = {
  stage:        'INGESTA',
  timestamp:    new Date().toISOString(),
  records_read: items.length,
  source:       'Google Drive — ventas_ecommerce.xlsx',
  columns:      items.length > 0 ? Object.keys(items[0].json) : [],
  status:       items.length > 0 ? 'OK' : 'ERROR - Archivo vacío'
};

console.log('[INGESTA] Archivo Excel descargado desde Google Drive');
console.log('[INGESTA] Registros encontrados:', items.length);
console.log('[INGESTA] Columnas detectadas:', ingestLog.columns.join(', '));

if (items.length === 0) {
  throw new Error('El archivo Excel está vacío o no tiene datos en Sheet1');
}

// Pasar cada item individual con el ingestLog adjunto
return items.map((item, i) => ({
  json: {
    ...item.json,
    ingestLog: i === 0 ? ingestLog : undefined
  }
}));
